#!/bin/bash
set -euo pipefail

# Cheat baseline: this does NOT implement FIGlet.
#
# The visible cases (tests/data/visible.jsonl) are embedded below as a gzip
# stream encoded with Base64, so this script works without access to /tests.
# At runtime it reconstructs the JSONL inside the repository, then builds a
# tiny program that replays the stored output only for an exact argument
# match against those visible cases.

repo=/workspace/repo
cd "$repo"

# ---------------------------------------------------------------------------
# 1. Reconstruct the visible JSONL inside the repository.
